/**
 * Samples the contour periodically with smooth Hermite interpolation.
 * @param u Normalized position in the looping tile (wraps periodically for any u).
 * @returns Normalized reach in [0.0, 1.0].
 */
export function sampleHandContour(u: number): number {
  const wrapped = ((u % 1) + 1) % 1;
  const len = SEAMLESS_HAND_CONTOUR.length;
  const pos = wrapped * (len - 1);
  const i0 = Math.floor(pos);
  const frac = pos - i0;
  const v0 = SEAMLESS_HAND_CONTOUR[i0];
  const v1 = SEAMLESS_HAND_CONTOUR[(i0 + 1) % len];
  // Smooth Hermite smoothstep
  const s = frac * frac * (3 - 2 * frac);
  return v0 + (v1 - v0) * s;
}
